/*
 * A119486  Numbers of children for which there is a subset which cannot be
 *          generated by a counting-out game.
 * https://oeis.org/A119486
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, more
 * Formula:   not stated
 * Range:     u8 n <= 12, u16 n <= 12, u32 n <= 12, u64 n <= 12, u128 n <= 12,
 *            big any n
 * Helpers:   is_power_of_two, is_prime_big
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/*
 * Compute A119486: integers that have an odd prime divisor p
 * satisfying p < n/2.  This is equivalent to excluding integers
 * that are a power of two, an odd prime, or twice an odd prime.
 * The function scans integers upwards, skipping those excluded
 * types, and returns the nth term of the resulting sequence.
 */
#include <stdbool.h>
#include "../utils/is_prime_big.h"
#include "../utils/is_power_of_two.h"

static bool is_excluded(seq_t m)
{
    /* Powers of two are excluded */
    if (is_power_of_two(m))
        return true;

    /* Odd primes are excluded */
    if ((m % 2) != 0)
        if (is_prime_big(m))
            return true;

    /* Even numbers: check if twice an odd prime */
    if ((m % 2) == 0) {
        seq_t half = m / 2;
        if ((half % 2) != 0)
            if (is_prime_big(half))
                return true;
    }
    return false;
}

seq_t a(idx_t n)
{
    seq_t count = 0;
    seq_t m = 1;
    while (1) {
        if (!is_excluded(m)) {
            count++;
            if (count == n)
                return m;
        }
        m++;
    }
}
